INSERT INTO `services` (`id`,`category_id`,`slug`,`name`,`summary`,`bullets`,`what_to_expect`,`ideal_for`,`duration_minutes`,`price`,`image`,`sort_order`,`is_featured`,`is_active`,`description`) VALUES (232, 1, 'scalp-micropigmentation', 'Scalp Micropigmentation', 'A thinning patch on your scalp doesn''t fix itself, and hats can only hide so much. Scalp micropigmentation deposits pigment dots that mimic real hair follicles, filling in patches for a fuller, denser look.', '["A full, natural-looking scalp with density restored", "Results last years with upkeep", "No surgery, no downtime"]', '[]', 'Thinning patches from alopecia, stress, or genetics • Scars from past hair transplants or injuries • Anyone tired of concealer powder that washes out • People wanting denser hair without a transplant • Those who shave their head and want a defined hairline', NULL, NULL, NULL, 9, 0, 1, NULL)
ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`name`=VALUES(`name`),`summary`=VALUES(`summary`),`bullets`=VALUES(`bullets`),`ideal_for`=VALUES(`ideal_for`),`duration_minutes`=VALUES(`duration_minutes`),`image`=VALUES(`image`),`sort_order`=VALUES(`sort_order`),`is_featured`=VALUES(`is_featured`),`is_active`=VALUES(`is_active`);

INSERT INTO `services` (`id`,`category_id`,`slug`,`name`,`summary`,`bullets`,`what_to_expect`,`ideal_for`,`duration_minutes`,`price`,`image`,`sort_order`,`is_featured`,`is_active`,`description`) VALUES (233, 1, 'lip-blush', 'Lip Blush', 'Lipstick smudges, fades and needs reapplying all day. Lip Blush deposits soft pigment into your lips, adding natural colour and definition that stays put from morning to night.', '["Natural-looking colour and definition for one to three years", "Perfecting session at 4–8 weeks", "No daily lipstick, no smudging"]', '[]', 'Pale or uneven lip tone needing natural colour • Thin lips wanting a more defined shape • Anyone tired of reapplying lipstick throughout the day • People wanting a soft, your-lips-but-better tint • Clients correcting faded or patchy past lip tattoos', NULL, NULL, NULL, 10, 0, 1, NULL)
